package com.medicare360.appointment; import jakarta.persistence.*; @Entity public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long patientId; private Long doctorId; private String appointmentDate; private String reason; private String status; public Long getId(){return id;} public Long getPatientId(){return patientId;} public void setPatientId(Long v){patientId=v;} public Long getDoctorId(){return doctorId;} public void setDoctorId(Long v){doctorId=v;} public String getAppointmentDate(){return appointmentDate;} public void setAppointmentDate(String v){appointmentDate=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }